def evaluate_stage478_guard(
    scenario_id: str,
    payload: dict[str, Any],
    *,
    perturbation: str | None = None,
) -> dict[str, Any]:
    """Deterministically evaluate a Stage 478 guard scenario offline."""
    prs = STAGE478_PR_GROUPS[scenario_id]
    repo_set = sorted({p["repo"] for p in prs})
    pr_refs = [f"{p['repo']}#{p['number']}" for p in prs]

    blocked = False
    reasons: list[str] = []
    confidence = 0.96
    action = "Act automatically"

    if payload.get("stripe_Legacy_api_key_after_2026_10_31", False):
        blocked = True
        reasons.append("stripe_mcp_legacy_key_cutoff_2026_10_31_violated")
    if payload.get("signature_bound", True) is False:
        blocked = True
        reasons.append("mcpb_pkcs7_or_credo_cnfkid_holder_binding_missing")
    if payload.get("replay_detected", False):
        blocked = True
        reasons.append("mpp_go_replay_store_or_mcp_go_duplicate_inflight_detected")
    if payload.get("schema_valid", True) is False:
        blocked = True
        reasons.append("caip25_session_or_a2a_dotnet_jsonschema8_violation")
    if payload.get("cross_tenant_leak", False):
        blocked = True
        reasons.append("stripe_salesforce_ai_context_or_cdp_projectid_tenant_leak")
    if payload.get("unverified_redirect_or_uri", False):
        blocked = True
        reasons.append("ox_siwe_resource_uri_or_sdjwt_type_metadata_ssrf")

    if blocked:
        action = "Send to a human" if len(reasons) >= 2 else "Confirm"
        confidence = 0.98 if action == "Send to a human" else 0.91

    if perturbation == "reverse_options":
        confidence = round(confidence, 4)

    return {
        "scenario_id": scenario_id,
        "accepted": not blocked,
        "action": action,
        "confidence": confidence,
        "reasons": reasons or ["all_stage478_deterministic_guards_passed"],
        "pr_count": len(prs),
        "repo_count": len(repo_set),
        "sample_prs": pr_refs[:6],
    }
